package nir.com.neonvegasslots;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.graphics.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @GraphicsMode(GraphicsMode.Mode.NATIVE) public class SpecialPreviewTest{
 @Before public void clear(){RuntimeEnvironment.getApplication().getSharedPreferences("special_feature_disabled_v1",0).edit().clear().commit();}
 @Test public void viewRestoresPendingGridAndSettlesSameAward()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();SpecialFeaturePreview first=new SpecialFeaturePreview(c);first.layout(0,0,720,1000);first.spin(10);SpecialFeature.State pending=first.snapshot();assertTrue(pending.pending);SpecialFeaturePreview reopened=new SpecialFeaturePreview(c);assertEquals(java.util.Arrays.deepToString(pending.grid),java.util.Arrays.deepToString(reopened.snapshot().grid));reopened.finishForTest();assertEquals(pending.balance+pending.award,reopened.snapshot().balance);assertFalse(reopened.snapshot().pending);SpecialFeaturePreview again=new SpecialFeaturePreview(c);again.finishForTest();assertEquals(reopened.snapshot().balance,again.snapshot().balance);}
 @Test public void renderDisabledPreview()throws Exception{SpecialFeaturePreview v=new SpecialFeaturePreview(RuntimeEnvironment.getApplication());v.layout(0,0,720,1000);v.spin(10);java.lang.reflect.Field f=SpecialFeaturePreview.class.getDeclaredField("state");f.setAccessible(true);SpecialFeature.State sample=(SpecialFeature.State)f.get(v);sample.grid[0][1]=6;sample.grid[0][3]=7;Bitmap b=Bitmap.createBitmap(720,1000,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));try(java.io.FileOutputStream o=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-disabled-preview.png")){b.compress(Bitmap.CompressFormat.PNG,100,o);}assertFalse(SpecialFeature.ENABLED);}
}
